// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *OfficeWhereInput) AddPredicates(predicates ...predicate.Office) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the OfficeWhereInput filter on the OfficeQuery builder.
func (i *OfficeWhereInput) Filter(q *OfficeQuery) (*OfficeQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyOfficeWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

