// Filter applies the PropertyWhereInput filter on the PropertyQuery builder.
func (i *PropertyWhereInput) Filter(q *PropertyQuery) (*PropertyQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyPropertyWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

